-- =============================================================================================
-- Migration: 0013_ashrae223_vocabulary.sql
-- ASHRAE 223P semantic concepts, for describing building systems alongside the machine standards
-- =============================================================================================
--
-- ⚠ VERIFY. The rows below are GENERATED by scripts/generate-ashrae223-vocabulary.mjs from the
-- open223 ontology `ontologies/223p.ttl` at version **v1.0.0-2026**, and the generator refuses to
-- run if upstream has moved off that pin. Names, labels and descriptions are read out of the
-- ontology rather than transcribed; nothing here was typed from a document.
--
-- **THE STANDARD IS NOT PUBLISHED.** ASHRAE 223 is still 223P / 223-202x and remains in public
-- review. This is a pre-publication ontology release, so a concept may be renamed, respecified or
-- withdrawn before the standard is final. That is a foreseeable event rather than a surprise, and
-- it is why the generator pins a version and fails on a bump instead of quietly adopting one.
--
-- The ontology declares its own licence in-band -- `dcterms:license` Apache-2.0,
-- `dcterms:rights "Copyright 2026 ASHRAE"` -- which is what permits redistributing these values
-- here. Adopting the vocabulary is not a conformance claim.
--
-- WHY THIS ONE GETS ITS OWN TABLE when four OPC UA companion specifications did not: those are all
-- OPC UA, so they are `companion_spec` values inside `opcua_vocabulary`. ASHRAE 223P is a different
-- standard by a different body with a different concept model -- an RDF class hierarchy, not a
-- browse-path address space -- and filing it under OPC UA would misstate its provenance.
--
-- SCOPE: the `s223:` namespace only. The ontology `owl:imports` QUDT for quantity kinds and units;
-- following that import would pull in a second, larger vocabulary under a separate licence, and
-- units are already covered by the MTConnect unit vocabulary.
-- =============================================================================================


-- ---------------------------------------------------------------------------------------------
-- The table
-- ---------------------------------------------------------------------------------------------
-- Reference data in the same sense as mtconnect_vocabulary and opcua_vocabulary: a row is a
-- concept the standard DEFINES, not a metric a device publishes.
--
-- Keyed on `name` alone, unlike opcua_vocabulary's (companion_spec, name): an RDF local name is
-- unique within its namespace by construction, which is what a namespace is for.

CREATE TABLE IF NOT EXISTS public.ashrae223_vocabulary (
    name text NOT NULL,
    concept_kind text NOT NULL,
    label text NOT NULL,
    description text,
    -- The immediate s223 superclass, when it has one. Kept because 563 flat concepts are not
    -- browsable: it is what lets the vocabulary panel offer sections instead of one long list.
    subclass_of text,
    semantic_id text NOT NULL,
    CONSTRAINT ashrae223_vocabulary_kind_valid CHECK (
      concept_kind = ANY (ARRAY['Class'::text, 'AbstractClass'::text, 'Concept'::text,
                                'Relation'::text, 'EnumerationKind'::text])
    ),
    -- Every id is issued by ASHRAE under its own namespace. A locally-minted id here would assert
    -- an interoperability nobody agreed to -- the rule archived migration 0029 sets out.
    CONSTRAINT ashrae223_vocabulary_semantic_id_namespace CHECK (
      semantic_id LIKE 'http://data.ashrae.org/standard223#%'
    )
);

DO $migration$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'ashrae223_vocabulary_pkey'
       AND conrelid = 'public.ashrae223_vocabulary'::regclass
  ) THEN
    ALTER TABLE ONLY public.ashrae223_vocabulary
        ADD CONSTRAINT ashrae223_vocabulary_pkey PRIMARY KEY (name);
  END IF;
END
$migration$;

COMMENT ON TABLE public.ashrae223_vocabulary IS
  'ASHRAE 223P semantic concepts, generated from the open223 ontology (Apache-2.0). Reference data, not deployment state -- a row is a concept the standard defines. ⚠ The standard is still in public review; concepts may move before publication.';
COMMENT ON COLUMN public.ashrae223_vocabulary.subclass_of IS
  'Immediate s223 superclass, or NULL at the top of the hierarchy. Used to give the vocabulary panel browsable sections.';

ALTER TABLE public.ashrae223_vocabulary ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS ashrae223_vocabulary_select_authenticated ON public.ashrae223_vocabulary;
CREATE POLICY ashrae223_vocabulary_select_authenticated
    ON public.ashrae223_vocabulary FOR SELECT TO authenticated USING (true);

-- No write policy at all, matching the other vocabularies: the generated seed below is the only
-- writer, and it runs as the migration role.
REVOKE ALL ON TABLE public.ashrae223_vocabulary FROM PUBLIC;
REVOKE ALL ON TABLE public.ashrae223_vocabulary FROM anon;
GRANT SELECT ON TABLE public.ashrae223_vocabulary TO authenticated;
GRANT ALL ON TABLE public.ashrae223_vocabulary TO service_role;


-- ---------------------------------------------------------------------------------------------
-- The metric group these concepts file under
-- ---------------------------------------------------------------------------------------------
-- ONE group, not one per concept. `enforce_metric_group_spelling()` makes the first spelling of a
-- group permanent, and registering 563 of them -- for a vocabulary whose standard is not yet
-- published -- would permanently fix a naming that the standard itself may still change. A BMS
-- point is named `Building/<concept>` until there is a reason for more.

INSERT INTO public.metric_groups (id, name, description, standard)
VALUES ('9d3a4f2e-6b1c-4e58-9a77-2f5c8d1b4e60', 'Building',
        'ASHRAE 223P building system points -- HVAC, electrical and the sensing around them',
        'ASHRAE 223P')
ON CONFLICT DO NOTHING;


